// GetStarGifts returns the list of available star gifts for purchase.
func (t *TelegramCore) GetStarGifts() (*StarGiftsResult, error) {
	t.mu.RLock()
	defer t.mu.RUnlock()
	if !t.authed || t.api == nil {
		return nil, ErrAuth
	}

	result, err := t.api.PaymentsGetStarGifts(t.ctx, 0)
	if err != nil {
		return nil, fmt.Errorf("get star gifts: %w", err)
	}
	sg, ok := result.(*tg.PaymentsStarGifts)
	if !ok {
		return &StarGiftsResult{}, nil
	}

	res := &StarGiftsResult{}
	for _, g := range sg.Gifts {
		gift, ok := g.(*tg.StarGift)
		if !ok {
			continue
		}
		if gift.SoldOut {
			continue
		}
		item := StarGiftItem{
			ID:    gift.ID,
			Stars: gift.Stars,
		}
		item.Limited = gift.Limited
		item.Birthday = gift.Birthday
		if gift.Limited {
			item.Remaining, _ = gift.GetAvailabilityRemains()
			item.Total, _ = gift.GetAvailabilityTotal()
		}
		if doc, ok := gift.Sticker.(*tg.Document); ok {
			item.ThumbB64 = extractStrippedThumbB64(doc.Thumbs)
		}
		res.Gifts = append(res.Gifts, item)
	}
	return res, nil
}

// GetPinnedStarGifts returns the pinned (saved) star gifts for a given peer, max 6.
func (t *TelegramCore) GetPinnedStarGifts(chatID string) (*PinnedGiftsResult, error) {
	t.mu.RLock()
	defer t.mu.RUnlock()
	if !t.authed || t.api == nil {
		return nil, ErrAuth
	}

	peer, err := t.resolvePeer(chatID)
	if err != nil {
		return nil, fmt.Errorf("resolve peer: %w", err)
	}
	inputPeer, err := t.toInputPeer(peer)
	if err != nil {
		return nil, fmt.Errorf("to input peer: %w", err)
	}

	req := &tg.PaymentsGetSavedStarGiftsRequest{
		Peer:           inputPeer,
		ExcludeUnsaved: true,
		Limit:          6,
	}
	req.SetFlags()
	result, err := t.api.PaymentsGetSavedStarGifts(t.ctx, req)
	if err != nil {
		return nil, fmt.Errorf("get pinned star gifts: %w", err)
	}

	res := &PinnedGiftsResult{}
	for _, sg := range result.Gifts {
		if !sg.PinnedToTop {
			continue
		}
		item := PinnedGiftItem{}
		switch g := sg.Gift.(type) {
		case *tg.StarGift:
			item.ID = g.ID
			if doc, ok := g.Sticker.(*tg.Document); ok {
				item.ThumbB64 = extractStrippedThumbB64(doc.Thumbs)
			}
		case *tg.StarGiftUnique:
			item.ID = g.ID
		}
		res.Gifts = append(res.Gifts, item)
		if len(res.Gifts) >= 6 {
			break
		}
	}
	return res, nil
}

func (t *TelegramCore) SendStarGift(chatID string, giftID int64) error {
	inputPeer, unlock, err := t.withPeer(chatID)
	if err != nil {
		return err
	}
	defer unlock()

	invoice := &tg.InputInvoiceStarGift{
		Peer:   inputPeer,
		GiftID: giftID,
	}
	rawForm, err := t.api.PaymentsGetPaymentForm(t.ctx, &tg.PaymentsGetPaymentFormRequest{
		Invoice: invoice,
	})
	if err != nil {
		return fmt.Errorf("get gift payment form: %w", err)
	}
	form, ok := rawForm.(*tg.PaymentsPaymentForm)
	if !ok {
		return fmt.Errorf("unexpected payment form type: %T", rawForm)
	}
	_, err = t.api.PaymentsSendPaymentForm(t.ctx, &tg.PaymentsSendPaymentFormRequest{
		FormID:  form.FormID,
		Invoice: invoice,
		Credentials: &tg.InputPaymentCredentials{
			Save: false,
			Data: tg.DataJSON{Data: "{}"},
		},
	})
	if err != nil {
		return fmt.Errorf("send star gift: %w", err)
	}
	return nil
}

