func (t *TelegramCore) GetBoostsJSON(chatID string) (map[string]interface{}, error) {
	t.mu.RLock(); defer t.mu.RUnlock()
	if !t.authed || t.api == nil { return nil, ErrAuth }
	peer, err := t.resolvePeer(chatID); if err != nil { return nil, err }
	inputPeer, err := t.toInputPeer(peer); if err != nil { return nil, err }
	status, err := t.api.PremiumGetBoostsStatus(t.ctx, inputPeer)
	if err != nil { return nil, err }
	out := map[string]interface{}{
		"level":               status.Level,
		"boosts":              status.Boosts,
		"current_level_boosts": status.CurrentLevelBoosts,
		"next_level_boosts":   status.NextLevelBoosts,
		"gift_boosts":         status.GiftBoosts,
		"my_boost":            status.MyBoost,
		"boost_url":           status.BoostURL,
	}
	if pa := status.PremiumAudience; pa.Total > 0 {
		out["premium_audience"] = map[string]interface{}{
			"part":  pa.Part,
			"total": pa.Total,
		}
	}
	if slots, ok := status.GetMyBoostSlots(); ok {
		out["my_boost_slots"] = slots
	}
	if prepaid, ok := status.GetPrepaidGiveaways(); ok && len(prepaid) > 0 {
		var giveaways []map[string]interface{}
		for _, pg := range prepaid {
			switch g := pg.(type) {
			case *tg.PrepaidGiveaway:
				// Premium subscriptions — boost count is quantity * multiplier
				// (computed UI-side); no credits field.
				giveaways = append(giveaways, map[string]interface{}{
					"id":       g.ID,
					"months":   g.Months,
					"quantity": g.Quantity,
					"date":     g.Date,
				})
			case *tg.PrepaidStarsGiveaway:
				// Telegram Stars giveaway (GiveawayTypeRow::Type::PrepaidCredits):
				// carries the star amount + an explicit boost count.
				giveaways = append(giveaways, map[string]interface{}{
					"id":       g.ID,
					"credits":  g.Stars,
					"quantity": g.Quantity,
					"boosts":   g.Boosts,
					"date":     g.Date,
				})
			}
		}
		out["prepaid_giveaways"] = giveaways
	}
	return out, nil
}

func (t *TelegramCore) GetBoostsListJSON(chatID string, isGifts bool, offset string) (map[string]interface{}, error) {
	t.mu.RLock(); defer t.mu.RUnlock()
	if !t.authed || t.api == nil { return nil, ErrAuth }
	peer, err := t.resolvePeer(chatID); if err != nil { return nil, err }
	inputPeer, err := t.toInputPeer(peer); if err != nil { return nil, err }
	req := &tg.PremiumGetBoostsListRequest{
		Peer:   inputPeer,
		Offset: offset,
		Limit:  50,
	}
	if isGifts {
		req.SetGifts(true)
	}
	list, err := t.api.PremiumGetBoostsList(t.ctx, req)
	if err != nil { return nil, err }
	out := map[string]interface{}{
		"count": list.Count,
	}
	if nextOff, ok := list.GetNextOffset(); ok {
		out["next_offset"] = nextOff
	}
	// Cache booster users so getUserAvatarB64 can resolve their photo + access hash.
	t.cacheEntities(list.Users, nil)
	var boosters []map[string]interface{}
	userMap := map[int64]tg.UserClass{}
	for _, u := range list.Users {
		if usr, ok := u.(*tg.User); ok {
			userMap[usr.ID] = usr
		}
	}
	for _, b := range list.Boosts {
		row := map[string]interface{}{
			"id":      b.ID,
			"date":    b.Date,
			"expires": b.Expires,
		}
		if b.Gift { row["gift"] = true }
		if b.Giveaway { row["giveaway"] = true }
		if b.Unclaimed { row["unclaimed"] = true }
		if uid, ok := b.GetUserID(); ok {
			row["user_id"] = uid
			if u, exists := userMap[uid]; exists {
				if usr, ok := u.(*tg.User); ok {
					name := usr.FirstName
					if usr.LastName != "" { name += " " + usr.LastName }
					row["user_name"] = name
				}
			}
			// Real-user booster userpic so the row renders the actual avatar
			// instead of the letter placeholder (generatePaintUserpicCallback,
			// info_statistics_list_controllers.cpp:507).
			if av := t.getUserAvatarB64(uid); av != "" {
				row["avatar_b64"] = av
			}
		}
		if mult, ok := b.GetMultiplier(); ok {
			row["multiplier"] = mult
		}
		boosters = append(boosters, row)
	}
	out["boosters"] = boosters
	return out, nil
}

func (t *TelegramCore) GetGiftCodeOptions(chatID string) ([]map[string]interface{}, error) {
	t.mu.RLock(); defer t.mu.RUnlock()
	if !t.authed || t.api == nil { return nil, ErrAuth }
	req := &tg.PaymentsGetPremiumGiftCodeOptionsRequest{}
	if chatID != "" {
		peer, err := t.resolvePeer(chatID); if err != nil { return nil, err }
		inputPeer, err := t.toInputPeer(peer); if err != nil { return nil, err }
		req.SetBoostPeer(inputPeer)
	}
	options, err := t.api.PaymentsGetPremiumGiftCodeOptions(t.ctx, req)
	if err != nil { return nil, err }
	var result []map[string]interface{}
	for _, opt := range options {
		row := map[string]interface{}{
			"users":    opt.Users,
			"months":   opt.Months,
			"currency": opt.Currency,
			"amount":   opt.Amount,
		}
		if sp, ok := opt.GetStoreProduct(); ok {
			row["store_product"] = sp
		}
		if sq, ok := opt.GetStoreQuantity(); ok {
			row["store_quantity"] = sq
		}
		result = append(result, row)
	}
	return result, nil
}

func (t *TelegramCore) LaunchPrepaidGiveaway(chatID string, giveawayID int64, params map[string]interface{}) error {
	t.mu.RLock(); defer t.mu.RUnlock()
	if !t.authed || t.api == nil { return ErrAuth }
	peer, err := t.resolvePeer(chatID); if err != nil { return err }
	inputPeer, err := t.toInputPeer(peer); if err != nil { return err }

	onlyNew, _ := params["only_new_subscribers"].(bool)
	winnersVisible, _ := params["winners_are_visible"].(bool)
	prizeDesc, _ := params["prize_description"].(string)
	untilDate, _ := params["until_date"].(float64)
	randomID, _ := params["random_id"].(float64)

	var countries []string
	if cs, ok := params["countries"].([]interface{}); ok {
		for _, c := range cs {
			if s, ok := c.(string); ok {
				countries = append(countries, s)
			}
		}
	}

	var additionalPeers []tg.InputPeerClass
	if aps, ok := params["additional_peers"].([]interface{}); ok {
		for _, ap := range aps {
			if apStr, ok := ap.(string); ok {
				p, err := t.resolvePeer(apStr)
				if err != nil { continue }
				ip, err := t.toInputPeer(p)
				if err != nil { continue }
				additionalPeers = append(additionalPeers, ip)
			}
		}
	}

	purpose := &tg.InputStorePaymentPremiumGiveaway{
		BoostPeer: inputPeer,
		Currency:  "USD",
		Amount:    0,
	}
	if onlyNew {
		purpose.SetOnlyNewSubscribers(true)
	}
	if winnersVisible {
		purpose.SetWinnersAreVisible(true)
	}
	if len(additionalPeers) > 0 {
		purpose.SetAdditionalPeers(additionalPeers)
	}
	if len(countries) > 0 {
		purpose.SetCountriesISO2(countries)
	}
	if prizeDesc != "" {
		purpose.SetPrizeDescription(prizeDesc)
	}
	if untilDate > 0 {
		purpose.UntilDate = int(untilDate)
	}
	if randomID > 0 {
		purpose.RandomID = int64(randomID)
	}

	_, err = t.api.PaymentsLaunchPrepaidGiveaway(t.ctx, &tg.PaymentsLaunchPrepaidGiveawayRequest{
		Peer:       inputPeer,
		GiveawayID: giveawayID,
		Purpose:    purpose,
	})
	return err
}

func (t *TelegramCore) LaunchRandomGiveaway(chatID string, params map[string]interface{}) (map[string]interface{}, error) {
	t.mu.RLock(); defer t.mu.RUnlock()
	if !t.authed || t.api == nil { return nil, ErrAuth }
	peer, err := t.resolvePeer(chatID); if err != nil { return nil, err }
	inputPeer, err := t.toInputPeer(peer); if err != nil { return nil, err }

	users, _ := params["users"].(float64)
	months, _ := params["months"].(float64)
	currency, _ := params["currency"].(string)
	amount, _ := params["amount"].(float64)
	onlyNew, _ := params["only_new_subscribers"].(bool)
	winnersVisible, _ := params["winners_are_visible"].(bool)
	prizeDesc, _ := params["prize_description"].(string)
	untilDate, _ := params["until_date"].(float64)
	randomID, _ := params["random_id"].(float64)
	storeProduct, _ := params["store_product"].(string)
	storeQuantity, _ := params["store_quantity"].(float64)

	var countries []string
	if cs, ok := params["countries"].([]interface{}); ok {
		for _, c := range cs {
			if s, ok := c.(string); ok {
				countries = append(countries, s)
			}
		}
	}

	var additionalPeers []tg.InputPeerClass
	if aps, ok := params["additional_peers"].([]interface{}); ok {
		for _, ap := range aps {
			if apStr, ok := ap.(string); ok {
				p, err := t.resolvePeer(apStr)
				if err != nil { continue }
				ip, err := t.toInputPeer(p)
				if err != nil { continue }
				additionalPeers = append(additionalPeers, ip)
			}
		}
	}

	purpose := &tg.InputStorePaymentPremiumGiveaway{
		BoostPeer: inputPeer,
		Currency:  currency,
		Amount:    int64(amount),
	}
	if onlyNew {
		purpose.SetOnlyNewSubscribers(true)
	}
	if winnersVisible {
		purpose.SetWinnersAreVisible(true)
	}
	if len(additionalPeers) > 0 {
		purpose.SetAdditionalPeers(additionalPeers)
	}
	if len(countries) > 0 {
		purpose.SetCountriesISO2(countries)
	}
	if prizeDesc != "" {
		purpose.SetPrizeDescription(prizeDesc)
	}
	if untilDate > 0 {
		purpose.UntilDate = int(untilDate)
	}
	if randomID > 0 {
		purpose.RandomID = int64(randomID)
	}

	option := tg.PremiumGiftCodeOption{
		Users:    int(users),
		Months:   int(months),
		Currency: currency,
		Amount:   int64(amount),
	}
	if storeProduct != "" {
		option.SetStoreProduct(storeProduct)
	}
	if storeQuantity > 0 {
		option.SetStoreQuantity(int(storeQuantity))
	}

	invoice := &tg.InputInvoicePremiumGiftCode{
		Purpose: purpose,
		Option:  option,
	}

	rawForm, err := t.api.PaymentsGetPaymentForm(t.ctx, &tg.PaymentsGetPaymentFormRequest{
		Invoice: invoice,
	})
	if err != nil {
		return nil, fmt.Errorf("get payment form: %w", err)
	}
	form, ok := rawForm.(*tg.PaymentsPaymentForm)
	if !ok {
		return nil, fmt.Errorf("unexpected payment form type: %T", rawForm)
	}

	result := map[string]interface{}{
		"form_id": form.FormID,
		"bot_id":  form.BotID,
		"title":   form.Title,
	}
	if form.URL != "" {
		result["url"] = form.URL
	}
	return result, nil
}

func (t *TelegramCore) GetStarsGiveawayOptions() ([]map[string]interface{}, error) {
	t.mu.RLock(); defer t.mu.RUnlock()
	if !t.authed || t.api == nil { return nil, ErrAuth }
	options, err := t.api.PaymentsGetStarsGiveawayOptions(t.ctx)
	if err != nil { return nil, err }
	var result []map[string]interface{}
	for _, opt := range options {
		row := map[string]interface{}{
			"stars":         opt.Stars,
			"yearly_boosts": opt.YearlyBoosts,
			"currency":      opt.Currency,
			"amount":        opt.Amount,
			"extended":      opt.Extended,
			"is_default":    opt.Default,
		}
		if sp, ok := opt.GetStoreProduct(); ok {
			row["store_product"] = sp
		}
		var winners []map[string]interface{}
		for _, w := range opt.Winners {
			winners = append(winners, map[string]interface{}{
				"users":          w.Users,
				"per_user_stars": w.PerUserStars,
				"is_default":     w.Default,
			})
		}
		row["winners"] = winners
		result = append(result, row)
	}
	return result, nil
}

