func (t *TelegramCore) GetMessageStatsJSON(chatID string, msgID int) (map[string]interface{}, error) {
	t.mu.RLock(); defer t.mu.RUnlock()
	if !t.authed || t.api == nil { return nil, ErrAuth }
	peer, err := t.resolvePeer(chatID); if err != nil { return nil, err }
	ch, ok := peer.(*tg.PeerChannel); if !ok { return nil, fmt.Errorf("not a channel") }
	hash, _ := t.resolveChannelAccessHash(ch.ChannelID)
	inputCh := &tg.InputChannel{ChannelID: ch.ChannelID, AccessHash: hash}
	result, err := t.api.StatsGetMessageStats(t.ctx, &tg.StatsGetMessageStatsRequest{
		Channel: inputCh,
		MsgID: msgID,
	})
	if err != nil { return nil, err }
	charts := []map[string]interface{}{}
	if c := statsGraphToMap("Interactions", result.ViewsGraph, "DoubleLinear"); c != nil {
		charts = append(charts, c)
	}
	if c := statsGraphToMap("Reactions By Emotion", result.ReactionsByEmotionGraph, "Bar"); c != nil {
		charts = append(charts, c)
	}
	out := map[string]interface{}{"charts": charts}

	fwds, ferr := t.api.StatsGetMessagePublicForwards(t.ctx, &tg.StatsGetMessagePublicForwardsRequest{
		Channel: inputCh,
		MsgID:   msgID,
		Limit:   100,
	})
	if ferr == nil && fwds != nil {
		out["public_forwards_count"] = fwds.Count
		chatMap := map[int64]tg.ChatClass{}
		for _, c := range fwds.Chats {
			switch v := c.(type) {
			case *tg.Chat:
				chatMap[v.ID] = v
			case *tg.Channel:
				chatMap[v.ID] = v
			}
		}
		userMap := map[int64]tg.UserClass{}
		for _, u := range fwds.Users {
			if usr, ok := u.(*tg.User); ok {
				userMap[usr.ID] = usr
			}
		}
		var forwards []map[string]interface{}
		for _, f := range fwds.Forwards {
			switch pf := f.(type) {
			case *tg.PublicForwardMessage:
				msg, ok := pf.Message.(*tg.Message)
				if !ok { continue }
				row := map[string]interface{}{"type": "message"}
				var peerID int64
				switch p := msg.PeerID.(type) {
				case *tg.PeerChannel:
					peerID = p.ChannelID
				case *tg.PeerChat:
					peerID = p.ChatID
				case *tg.PeerUser:
					peerID = p.UserID
				}
				if ch, ok := chatMap[peerID]; ok {
					switch v := ch.(type) {
					case *tg.Channel:
						row["name"] = v.Title
						row["peer_id"] = fmt.Sprintf("channel_%d", v.ID)
						// Subscriber/member count for the forward status line
						// ("<subscribers/members>, <views> views",
						// info_statistics_list_controllers.cpp:421-434).
						if pc, ok := v.GetParticipantsCount(); ok {
							row["members"] = pc
						}
						row["is_megagroup"] = v.Megagroup
					case *tg.Chat:
						row["name"] = v.Title
						row["peer_id"] = fmt.Sprintf("chat_%d", v.ID)
						row["members"] = v.ParticipantsCount
						row["is_megagroup"] = true
					}
				} else if u, ok := userMap[peerID]; ok {
					if usr, ok := u.(*tg.User); ok {
						name := usr.FirstName
						if usr.LastName != "" { name += " " + usr.LastName }
						row["name"] = name
						row["peer_id"] = fmt.Sprintf("user_%d", usr.ID)
					}
				}
				row["msg_id"] = msg.ID
				row["views"] = msg.Views
				row["date"] = msg.Date
				forwards = append(forwards, row)
			case *tg.PublicForwardStory:
				row := map[string]interface{}{"type": "story"}
				switch p := pf.Peer.(type) {
				case *tg.PeerChannel:
					if ch, ok := chatMap[p.ChannelID]; ok {
						if v, ok := ch.(*tg.Channel); ok {
							row["name"] = v.Title
							row["peer_id"] = fmt.Sprintf("channel_%d", v.ID)
						}
					}
				}
				forwards = append(forwards, row)
			}
		}
		out["public_forwards"] = forwards
		if fwds.NextOffset != "" {
			out["next_offset"] = fwds.NextOffset
		}
	}

	// Re-fetch the live view / forward / reaction counters via channels.GetMessages
	// so the overview shows fresh numbers, not a recent-post snapshot, and the
	// cards render whenever the value is present (api_statistics.cpp:405).
	if msgs, mErr := t.api.ChannelsGetMessages(t.ctx, &tg.ChannelsGetMessagesRequest{
		Channel: inputCh,
		ID:      []tg.InputMessageClass{&tg.InputMessageID{ID: msgID}},
	}); mErr == nil {
		var list []tg.MessageClass
		switch m := msgs.(type) {
		case *tg.MessagesChannelMessages:
			list = m.Messages
		case *tg.MessagesMessages:
			list = m.Messages
		}
		for _, mc := range list {
			msg, ok := mc.(*tg.Message)
			if !ok || msg.ID != msgID {
				continue
			}
			if v, ok := msg.GetViews(); ok {
				out["views"] = v
			}
			if f, ok := msg.GetForwards(); ok {
				out["forwards"] = f
			}
			if r, ok := msg.GetReactions(); ok {
				total := 0
				for _, rc := range r.Results {
					total += rc.Count
				}
				out["reactions"] = total
			}
			break
		}
	}

	return out, nil
}

// GetMessagePublicForwardsJSON returns a page of public forwards given an offset cursor.
func (t *TelegramCore) GetMessagePublicForwardsJSON(chatID string, msgID int, offset string) (map[string]interface{}, error) {
	t.mu.RLock(); defer t.mu.RUnlock()
	if !t.authed || t.api == nil { return nil, ErrAuth }
	peer, err := t.resolvePeer(chatID); if err != nil { return nil, err }
	ch, ok := peer.(*tg.PeerChannel); if !ok { return nil, fmt.Errorf("not a channel") }
	hash, _ := t.resolveChannelAccessHash(ch.ChannelID)
	inputCh := &tg.InputChannel{ChannelID: ch.ChannelID, AccessHash: hash}
	fwds, err := t.api.StatsGetMessagePublicForwards(t.ctx, &tg.StatsGetMessagePublicForwardsRequest{
		Channel: inputCh,
		MsgID:   msgID,
		Offset:  offset,
		Limit:   100,
	})
	if err != nil { return nil, err }
	out := map[string]interface{}{}
	chatMap := map[int64]tg.ChatClass{}
	for _, c := range fwds.Chats {
		switch v := c.(type) {
		case *tg.Chat: chatMap[v.ID] = v
		case *tg.Channel: chatMap[v.ID] = v
		}
	}
	var forwards []map[string]interface{}
	for _, f := range fwds.Forwards {
		switch pf := f.(type) {
		case *tg.PublicForwardMessage:
			msg, ok := pf.Message.(*tg.Message)
			if !ok { continue }
			row := map[string]interface{}{"type": "message"}
			var peerID int64
			switch p := msg.PeerID.(type) {
			case *tg.PeerChannel: peerID = p.ChannelID
			case *tg.PeerChat: peerID = p.ChatID
			case *tg.PeerUser: peerID = p.UserID
			}
			if ch, ok := chatMap[peerID]; ok {
				switch v := ch.(type) {
				case *tg.Channel:
					row["name"] = v.Title
					row["peer_id"] = fmt.Sprintf("channel_%d", v.ID)
					if pc, ok := v.GetParticipantsCount(); ok {
						row["members"] = pc
					}
					row["is_megagroup"] = v.Megagroup
				case *tg.Chat:
					row["name"] = v.Title
					row["peer_id"] = fmt.Sprintf("chat_%d", v.ID)
					row["members"] = v.ParticipantsCount
					row["is_megagroup"] = true
				}
			}
			row["msg_id"] = msg.ID
			row["views"] = msg.Views
			row["date"] = msg.Date
			forwards = append(forwards, row)
		case *tg.PublicForwardStory:
			row := map[string]interface{}{"type": "story"}
			switch p := pf.Peer.(type) {
			case *tg.PeerChannel:
				if ch, ok := chatMap[p.ChannelID]; ok {
					if v, ok := ch.(*tg.Channel); ok {
						row["name"] = v.Title
						row["peer_id"] = fmt.Sprintf("channel_%d", v.ID)
					}
				}
			}
			forwards = append(forwards, row)
		}
	}
	out["forwards"] = forwards
	if fwds.NextOffset != "" {
		out["next_offset"] = fwds.NextOffset
	}
	return out, nil
}

